package org.community.giving;
import jakarta.persistence.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"election_id","voter_id","category","subcategory"})) public class Vote { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="election_id") public Long electionId; @Column(name="voter_id") public Long voterId; @Column(name="candidate_id") public Long candidateId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="election_id",insertable=false,updatable=false,foreignKey=@ForeignKey(name="fk_vote_election")) public Election election; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="voter_id",insertable=false,updatable=false,foreignKey=@ForeignKey(name="fk_vote_voter")) public Member voter; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="candidate_id",insertable=false,updatable=false,foreignKey=@ForeignKey(name="fk_vote_candidate")) public Candidate candidate; public String category, subcategory; }
